'use client';
const require_breadcrumbs = require("./breadcrumbs.cjs");
const require_breadcrumbs_item = require("./breadcrumbs-item.cjs");
const require_breadcrumbs_link = require("./breadcrumbs-link.cjs");
const require_breadcrumbs_list = require("./breadcrumbs-list.cjs");
//#region src/components/breadcrumbs/index.ts
/**
* `Breadcrumbs` is a component that displays a list of breadcrumbs.
*
* @example
* <Breadcrumbs aria-label='Du er her:'>
*  <Breadcrumbs.Link href='#' aria-label='Tilbake til Nivå 1'>
*    Nivå 1
*  </Breadcrumbs.Link>
*  <Breadcrumbs.List>
*    <Breadcrumbs.Item>
*      <Breadcrumbs.Link href='#'>Nivå 1</Breadcrumbs.Link>
*    </Breadcrumbs.Item>
*    <Breadcrumbs.Item>
*      <Breadcrumbs.Link href='#'>Nivå 2</Breadcrumbs.Link>
*    </Breadcrumbs.Item>
*  </Breadcrumbs.List>
* </Breadcrumbs>
*/
const BreadcrumbsComponent = Object.assign(require_breadcrumbs.Breadcrumbs, {
	List: require_breadcrumbs_list.BreadcrumbsList,
	Item: require_breadcrumbs_item.BreadcrumbsItem,
	Link: require_breadcrumbs_link.BreadcrumbsLink
});
BreadcrumbsComponent.List.displayName = "Breadcrumbs.List";
BreadcrumbsComponent.Item.displayName = "Breadcrumbs.Item";
BreadcrumbsComponent.Link.displayName = "Breadcrumbs.Link";
//#endregion
exports.Breadcrumbs = BreadcrumbsComponent;
exports.BreadcrumbsItem = require_breadcrumbs_item.BreadcrumbsItem;
exports.BreadcrumbsLink = require_breadcrumbs_link.BreadcrumbsLink;
exports.BreadcrumbsList = require_breadcrumbs_list.BreadcrumbsList;
